Object.keys(o.acts).forEach(k => { const a = o.acts[k], p = pct(a.used || 0, a.est); extra.push('<span style="color:' + (p > 100 ? 'var(--text-danger)' : 'inherit') + '">' + esc(a.n + ': ' + fill(t.budLine, [fmt(a.used || 0, u), fmt(a.est, u), p])) + '</span>'); });
if (o.nc && o.r) extra.push(esc(fill(t.ncShare, [pct(o.nc, o.r)])));
if (extra.length) h += '<div class="s12" style="font-size:11px;margin:-2px 0 6px">' + extra.join(' · ') + '</div>';
