h += '<div class="sec" style="display:flex;gap:10px;align-items:baseline;flex-wrap:wrap' + (d.norm ? '' : ';color:var(--text-muted)') + '"><span>' + esc(dayName(D, d.d)) + '</span><span class="s12" style="font-weight:400">' + esc(fmt(reg, u) + ' · ' + (d.norm ? fill(t.norm, [fmt(d.norm, u)]) : t.norm0)) + '</span>';
if (sh >= 0.25) h += d.ok ? '<span class="s11">' + esc(t.accepted) + '</span>' : '<span style="font-size:12px;font-weight:400;color:var(--text-danger)">' + esc(fill(t.short, [fmt(sh, u)])) + '</span><button class="sb" data-a="acc" data-d="' + esc(d.d) + '">' + esc(t.accept) + '</button>';
h += '</div>';
