if (wk) { const why = submitBlock(D, t, rows); h += '<button class="b" data-a="submit"' + (why ? ' disabled' : '') + '>' + esc(fill(t.submit, [D.week])) + '</button>' + (why ? '<span class="s12" style="align-self:center">' + esc(why) + '</span>' : ''); }
h += '</div>';
if (S.err) h += '<div class="err">' + esc(S.err) + '</div>';
if (copy && S.copyText) h += '<textarea class="ta" readonly style="margin-top:8px !important">' + esc(S.copyText) + '</textarea>';
if (D.note) h += '<div class="s11" style="margin-top:8px">' + esc(D.note) + '</div>';
else if (!copy) h += '<div class="s11" style="margin-top:8px">' + esc(t.noWrite) + '</div>';
if (wk && (D.check || []).length) h += '<div class="sec">' + esc(t.check) + '</div>' + D.check.map(c => '<div class="s12" style="margin-bottom:4px">' + esc(c) + '</div>').join('');
